input.command:
find ~/.claude ~/Desktop ~/Downloads ~/Documents -maxdepth 3 -iname "*mist*" \( -iname "*.png" -o -iname "*.jpg" -o -iname "*.jpeg" -o -iname "*.webp" -o -iname "*.heic" \) 2>/dev/null
echo "--- recent images added in last day across common spots ---"
find ~/.claude ~/Desktop ~/Downloads -maxdepth 2 \( -iname "*.png" -o -iname "*.jpg" -o -iname "*.jpeg" -o -iname "*.webp" -o -iname "*.heic" \) -mtime -1 2>/dev/null -exec ls -la {} \;

input.new_string:
  command claude "$@"
}

# Swap which MIST portrait shows at launch, then relaunch claude to compare.
mist-form() {
  case "$1" in
    cloud) cp ~/.claude/mist-cloud.webp ~/.claude/mist.png && echo "MIST portrait → Cloud form" ;;
    human) cp ~/.claude/mist-human.webp ~/.claude/mist.png && echo "MIST portrait → evolved human form" ;;
    *) echo "usage: mist-form {cloud|human}" ;;
  esac
}

input.content:
import Foundation
import Vision
import CoreImage
import ImageIO
import CoreVideo

guard CommandLine.arguments.count == 3 else {
    FileHandle.standardError.write("usage: subjectmask <in> <out.png>\n".data(using: .utf8)!)
    exit(2)
}
let inPath = CommandLine.arguments[1]
let outPath = CommandLine.arguments[2]

guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: inPath) as CFURL, nil),
      let cgImage = CGImageSourceCreateImageAtIndex(src, 0, nil) else {
    FileHandle.standardError.write("failed to load image\n".data(using: .utf8)!)
    exit(1)
}

let handler = VNImageRequestHandler(cgImage: cgImage, options: [:])
let request = VNGenerateForegroundInstanceMaskRequest()
do {
    try handler.perform([request])
} catch {
    FileHandle.standardError.write("vision failed: \(error)\n".data(using: .utf8)!)
    exit(1)
}
guard let result = request.results?.first else {
    FileHandle.standardError.write("no foreground subject found\n".data(using: .utf8)!)
    exit(1)
}
do {
    let masked = try result.generateMaskedImage(
        ofInstances: result.allInstances,
        from: handler,
        croppedToInstancesExtent: false)
    let ciImage = CIImage(cvPixelBuffer: masked)
    let ctx = CIContext()
    let colorSpace = CGColorSpace(name: CGColorSpace.sRGB)!
    try ctx.writePNGRepresentation(of: ciImage,
        to: URL(fileURLWithPath: outPath),
        format: .RGBA8,
        colorSpace: colorSpace)
    print("wrote \(outPath)")
} catch {
    FileHandle.standardError.write("mask/write failed: \(error)\n".data(using: .utf8)!)
    exit(1)
}

input.command:
for f in ~/.claude/mist-cloud.png ~/.claude/mist-human.png; do
  echo "=== $f ==="
  echo -n "  top-left alpha:    "; magick "$f" -format "%[pixel:p{2,2}]" info:
  echo -n "  top-right alpha:   "; magick "$f" -format "%[pixel:p{w-3,2}]" info:
  echo -n "  center alpha:      "; magick "$f" -format "%[pixel:p{w/2,h/2}]" info:
  echo -n "  % fully transparent: "; magick "$f" -alpha extract -threshold 1% -format "%[fx:100*(1-mean)]" info:; echo "%"
done
